/* ---------------- Metrics Dashboard ---------------- */
function CustomBarTooltip({ active, payload }) {
    if (!active || !payload || !payload.length) return null;
    const d = payload[0].payload;
    return (
        <div
            style={{
                background: "#1B1830",
                border: "1px solid rgba(139,92,246,0.3)",
                borderRadius: 8,
                padding: "10px 14px",
                fontFamily: "'IBM Plex Mono', monospace",
            }}
        >
            <div style={{ color: "#F1EEFB", fontSize: 13, fontWeight: 600, whiteSpace: "pre-line" }}>
                {d.name.replace(/\n/g, " ")}
            </div>
            <div style={{ color: "#B794F6", fontSize: 12.5, marginTop: 4 }}>
                {d.metric ? `${d.metric}: ` : ""}
                {d.display ? d.display : `${d.value}%`}
            </div>
        </div>
    );
}

