/* ---------------- App ---------------- */
export default function Portfolio() {
    const [paletteOpen, setPaletteOpen] = useState(false);
    const [paletteProject, setPaletteProject] = useState(null);

    const scrollTo = (id) => {
        const el = document.getElementById(id);
        if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
    };

    useEffect(() => {
        const onKey = (e) => {
            if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
                e.preventDefault();
                setPaletteOpen((o) => !o);
            }
        };
        window.addEventListener("keydown", onKey);
        return () => window.removeEventListener("keydown", onKey);
    }, []);

    return (
        <div style={{ background: "#0B0A12", minHeight: "100vh" }}>
            <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap');
        * { box-sizing: border-box; }
        body { margin: 0; }
        a:focus-visible, button:focus-visible {
          outline: 2px solid #4FD1C5;
          outline-offset: 2px;
        }
        @media (max-width: 860px) {
          .sm-nav-links { display: none !important; }
          .sm-menu-btn { display: block !important; }
          .sm-hero-grid { grid-template-columns: 1fr !important; }
          .sm-hero-photo-wrap { order: -1; margin-bottom: 8px; }
          .sm-about-grid { grid-template-columns: 1fr !important; }
          .sm-metrics-top-grid { grid-template-columns: 1fr !important; }
          .sm-projects-grid { grid-template-columns: 1fr !important; }
          .sm-demo-grid { grid-template-columns: 1fr !important; }
          .sm-skills-grid { grid-template-columns: 1fr !important; }
        }
        @media (max-width: 1100px) and (min-width: 861px) {
          .sm-projects-grid { grid-template-columns: repeat(2, 1fr) !important; }
        }
        @media (prefers-reduced-motion: reduce) {
          * { animation: none !important; transition: none !important; }
        }
      `}</style>

            <Nav onNavigate={scrollTo} onOpenPalette={() => setPaletteOpen(true)} />
            <Hero onNavigate={scrollTo} />
            <About />
            <MetricsDashboard />
            <Projects />
            <LiveDemo />
            <Skills />
            <Contact />
            <Footer />

            <CommandPalette
                open={paletteOpen}
                onClose={() => setPaletteOpen(false)}
                onNavigate={(id) => {
                    scrollTo(id);
                }}
                onOpenProject={(project) => setPaletteProject(project)}
            />
            {paletteProject && (
                <ProjectModal project={paletteProject} onClose={() => setPaletteProject(null)} />
            )}
            <ChatBot />
        </div>
    );
}